Method.Source:
[Form]
public class AAXWHSLabelPreviewDialog extends FormRun
{
    // Contract with AAXWHSLabelPreviewController: args().parmObject() is an
    // AAXWHSLabelPreviewContext (parmPngList()->List of container, parmFinalZpl()->str,
    // parmBadgeText()->str).
    AAXWHSLabelPreviewContext   context;
    List                        pngs;           // List of container, one PNG per ^XA..^XZ block (ORIGINAL, unrotated source)
    int                         currentIndex;   // 1-based page index
    str                         currentUrl;     // temp-store URL of the page on display (rotated if turns>0)
    Map                         pageUrls;       // lazy temp-store URL cache, keyed by "page|turns" (String -> String)

    // Feature 1 (rotate clockwise 90, unlimited clicks): per-PAGE cumulative rotation state.
    // ALWAYS rotate FROM THE ORIGINAL container by the cumulative turn count â€” never re-rotate
    // a rotated PNG. pageTurns maps 1-based page -> turns (0..3).
    Map                         pageTurns;      // Integer -> Integer

    // Feature 2 (seed-record selection): identity needed for the dialog to re-render via
    // AAXWHSLabelPreviewController::buildContext.
    TableId                     layoutTableId;
    RecId                       layoutRecId;
    TableId                     seedTableId;
    RecId                       selectedSeedRecId;  // 0 = auto-resolve most-recent

    // Feature 3 (edit + save the raw SOURCE ZPL): whether this layout type is savable.
    boolean                     canSave;
}

/// <summary>
/// Reads the preview context from the caller, shows the first label image and the final ZPL.
/// </summary>
public void init()
{
    super();

    context = element.args().parmObject() as AAXWHSLabelPreviewContext;
    if (!context)
    {
        return;
    }

    element.initFromContext(context);
}

/// <summary>
/// (Re)initializes all form state from a preview context: PNGs, badge, final ZPL, the
/// data-source group, and â€” crucially â€” CLEARS all rotation state and URL caches before
/// rendering page 1. Called from init() and from the Refresh button.
/// </summary>
/// <param name = "_context">The preview context to bind.</param>
public void initFromContext(AAXWHSLabelPreviewContext _context)
{
    context = _context;
    pngs    = context.parmPngList();

    // CLEAR caches + rotation state: the new render has fresh containers, so any cached
    // temp-store URL or accumulated rotation from the previous seed record must be dropped
    // (temp-store URLs are short-lived and generated lazily on navigation).
    pageUrls  = new Map(Types::String, Types::String);   // key "page|turns" -> URL
    pageTurns = new Map(Types::Integer, Types::Integer);  // page -> cumulative turns (0..3)

    // Re-render identity + seed selection state.
    layoutTableId     = context.parmLayoutTableId();
    layoutRecId       = context.parmLayoutRecId();
    seedTableId       = context.parmSeedTableId();
    selectedSeedRecId = context.parmSeedRecId();

    // Badge near the image: "Live record: %1" or "Sample data".
    BadgeText.text(context.parmBadgeText());

    // EDITABLE raw SOURCE panel: the layout's stored text WITH $tokens$ (and, for template
    // layouts, the {{Header}}/{{Row}}/{{Footer}} blocks). This is what "Save to layout" persists
    // and what "Preview edits" re-renders — NEVER the translated result.
    SourceZplText.text(context.parmSourceZpl());

    // Read-only multiline TRANSLATED result (tokens substituted) — shows what the source
    // RENDERS to, and is the copy surface (CopyZpl affordance).
    ZplText.text(context.parmFinalZpl());

    // Save is a WRITE; only offer it for savable layout types (ZPL-type / document routing).
    canSave = context.parmCanSave();
    SourceZplText.allowEdit(canSave);
    SaveButton.enabled(canSave);
    SaveButton.visible(canSave);

    // Data-source group: show the seed table label and the currently selected record's
    // natural identifier (e.g. ContainerId), not its RecId.
    SeedTableLabel.text(context.parmSeedTableLabel());
    SeedRecordEdit.text(element.seedRecordIdentifierText(selectedSeedRecId));

    // "Label size" override box: repopulate from the context so a Refresh/Preview-edits cycle
    // keeps the user's chosen size. When the context carries no override (initial open / no
    // size box), fall back to the displayed defaults (4 x 6 in @ 203 DPI) and leave it OFF.
    boolean overrideOn = context.parmOverrideSize();
    OverrideSizeCheck.value(overrideOn);
    SizeWidthIn.realValue(context.parmOverrideWidthIn()  > 0 ? context.parmOverrideWidthIn()  : 4);
    SizeHeightIn.realValue(context.parmOverrideHeightIn() > 0 ? context.parmOverrideHeightIn() : 6);
    SizeDpi.value(context.parmOverrideDpi() > 0 ? context.parmOverrideDpi() : 203);
    element.applySizeControlsEnabled(overrideOn);

    currentIndex = 1;
    element.showPage(currentIndex);
}

/// <summary>
/// Displays the requested label page, uploading its PNG to temp store lazily.
/// </summary>
/// <param name = "_page">The 1-based page (label block) to display.</param>
public void showPage(int _page)
{
    int total = pngs ? pngs.elements() : 0;
    if (total == 0)
    {
        return;
    }

    if (_page < 1)
    {
        _page = 1;
    }
    else if (_page > total)
    {
        _page = total;
    }

    currentIndex = _page;
    currentUrl   = this.urlForPage(_page);

    // Bind the image control to the page's temp-store URL (proven URL-image pattern,
    // RetailMediaImageViewer / EcoResProductImage: imageLocation(URL) + normalImage(url)).
    PreviewImage.imageLocation(SysImageLocation::URL);
    PreviewImage.normalImage(currentUrl);

    // Pager text: "Label %1 of %2".
    PagerText.text(strFmt("@AAXWarehouseTools:LabelNofM", _page, total));

    // Prev/Next only meaningful for multi-label ZPL.
    PrevPageButton.visible(total > 1);
    NextPageButton.visible(total > 1);
    PrevPageButton.enabled(_page > 1);
    NextPageButton.enabled(_page < total);
}

/// <summary>
/// Returns the temp-store URL for a label page, uploading the PNG on first request.
/// </summary>
/// <param name = "_page">The 1-based page (label block).</param>
/// <returns>The temp-store URL for the page, or an empty string on failure.</returns>
private str urlForPage(int _page)
{
    int turns = this.turnsForPage(_page);

    // Cache key includes the cumulative rotation so each (page,turns) has a distinct URL â€”
    // a rotated page must never reuse the upright page's URL (Feature 1).
    str cacheKey = strFmt('%1|%2', _page, turns);

    // Temp-store URLs are short-lived: cache per (page,turns) and (re)generate on
    // navigation so a page opened after a delay still renders (no expired-URL 404).
    if (pageUrls.exists(cacheKey))
    {
        str cached = pageUrls.lookup(cacheKey);
        if (cached)
        {
            return cached;
        }
    }

    // List enumerator: walk to the _page-th ORIGINAL container (1-based). Rotation is
    // always applied FROM THE ORIGINAL by the cumulative turn count â€” never re-rotate a
    // rotated PNG (Feature 1).
    ListEnumerator listEnumerator = pngs.getEnumerator();
    int idx = 0;
    container pngContainer = conNull();
    while (listEnumerator.moveNext())
    {
        idx++;
        if (idx == _page)
        {
            pngContainer = listEnumerator.current();
            break;
        }
    }

    str url = '';
    if (conLen(pngContainer) > 0)
    {
        // Apply cumulative rotation from the original. turns == 0 => original bytes.
        container displayContainer = (turns == 0)
            ? pngContainer
            : AAXZplRenderService::rotatePng(pngContainer, turns);

        // container -> Stream (already-authored helper) -> temp store (stream-only).
        // Unique file name per (page,turns) avoids any client-side image cache collision.
        System.IO.MemoryStream stream = AAXZplRenderService::pngContainerToStream(displayContainer);
        if (stream)
        {
            url = File::SendFileToTempStore(stream, strFmt('LabelPreview_%1_%2.png', _page, turns));
        }
    }

    pageUrls.insert(cacheKey, url);
    return url;
}

/// <summary>
/// Returns the cumulative clockwise quarter-turns currently applied to a page (0..3).
/// </summary>
/// <param name = "_page">The 1-based page.</param>
/// <returns>The page's current rotation in quarter turns.</returns>
private int turnsForPage(int _page)
{
    if (pageTurns && pageTurns.exists(_page))
    {
        return pageTurns.lookup(_page);
    }

    return 0;
}

/// <summary>
/// Rotates the current page 90 degrees clockwise (unlimited clicks). Per-page cumulative
/// turns are tracked so navigation shows each page at its own rotation; rendering always
/// starts from the original container (Feature 1).
/// </summary>
public void rotateCurrentPage()
{
    int turns = this.turnsForPage(currentIndex);
    turns = (turns + 1) mod 4;
    pageTurns.insert(currentIndex, turns);

    // Re-show the current page; urlForPage rotates from the original by the new turn count.
    element.showPage(currentIndex);
}

/// <summary>
/// Opens the current page's PNG in the browser so the user can download it.
/// </summary>
public void downloadCurrentPage()
{
    // Proven download pattern (File.SendFileToUser / WhsExternalServiceInstances):
    // new Browser().navigate(url, false, false). currentUrl is the CURRENTLY DISPLAYED
    // (rotated) image URL, so Download honors the active rotation (Feature 1).
    if (currentUrl)
    {
        new Browser().navigate(currentUrl, false, false);
    }
}

/// <summary>
/// Re-renders the preview using the record currently chosen in the data-source selector.
/// Re-reads the layout row generically, rebuilds the context via the controller, and
/// re-initializes all form state (which clears rotation + URL caches).
/// </summary>
public void refreshPreview()
{
    AAXWHSLabelPreviewContext   newContext;
    Common                      layoutRecord;
    container                   sizeArgs = element.sizeOverrideArgs();

    layoutRecord = element.rereadLayoutRecord();
    if (layoutRecord.RecId == 0)
    {
        return;
    }

    // Pin the resolved seed table so buildContext re-renders against the SAME table the
    // selector looked up; selectedSeedRecId == 0 falls back to most-recent. The
    // "Label size" override (all 0 when off) drives the render size — label's own ^PW/^LL wins
    // by default; an explicit size overrides it (sizeArgs = [widthMm, heightMm, dpmm]).
    newContext = AAXWHSLabelPreviewController::buildContext(
        layoutRecord, seedTableId, selectedSeedRecId,
        conPeek(sizeArgs, 1), conPeek(sizeArgs, 2), conPeek(sizeArgs, 3));
    if (!newContext)
    {
        // A validation gate fired (already info()'d); leave the current preview untouched.
        return;
    }

    element.initFromContext(newContext);
}

/// <summary>
/// Re-reads the originating layout row generically (the same idiom Refresh uses), so the
/// edit/save actions operate on a fresh buffer of the correct table.
/// </summary>
/// <returns>The layout <c>Common</c> buffer (RecId 0 when not found / identity missing).</returns>
private Common rereadLayoutRecord()
{
    Common      layoutRecord;
    DictTable   layoutDictTable;

    if (!layoutTableId || !layoutRecId)
    {
        return layoutRecord;
    }

    // new DictTable(tableId).makeRecord() + select by RecId is the verified donor idiom
    // (AssetBookOriginalDocuments / AuditPolicyCaseBuilder), reused from refreshPreview().
    layoutDictTable = new DictTable(layoutTableId);
    layoutRecord    = layoutDictTable.makeRecord();

    select firstonly layoutRecord
        where layoutRecord.RecId == layoutRecId;

    return layoutRecord;
}

/// <summary>
/// Re-renders the preview from the edited SOURCE text WITHOUT saving (Feature 3). Reads the
/// editable Source-ZPL control, translates+renders it via
/// <c>AAXWHSLabelPreviewController::renderFromSource</c> against the current seed, and
/// re-initializes all form state (which clears rotation + URL caches).
/// </summary>
public void previewEdits()
{
    AAXWHSLabelPreviewContext   newContext;
    Common                      layoutRecord;
    str                         editedSource = SourceZplText.text();
    container                   sizeArgs = element.sizeOverrideArgs();

    if (!editedSource)
    {
        // Nothing to preview; leave the current image/translated ZPL untouched.
        return;
    }

    layoutRecord = element.rereadLayoutRecord();
    if (layoutRecord.RecId == 0)
    {
        return;
    }

    // Preview the UNSAVED edit: translate/render the override source (not the stored layout).
    // The "Label size" override (all 0 when off) drives the render size, same as Refresh.
    newContext = AAXWHSLabelPreviewController::renderFromSource(
        layoutRecord, editedSource, seedTableId, selectedSeedRecId,
        conPeek(sizeArgs, 1), conPeek(sizeArgs, 2), conPeek(sizeArgs, 3));

    if (!newContext)
    {
        // Layout type not previewable (already info()'d upstream); keep current preview.
        return;
    }

    element.initFromContext(newContext);
}

/// <summary>
/// Saves the edited raw SOURCE ZPL back to the layout (Feature 3), then re-previews the saved
/// state. Validates non-empty, calls <c>AAXWHSLabelPreviewController::saveSourceToLayout</c>
/// (which performs the Edit-access security gate) and <c>info()</c>s the returned message. On
/// success the dialog stays open showing the freshly saved/rendered state.
/// </summary>
public void saveSource()
{
    str editedSource = SourceZplText.text();
    container result;
    boolean saved;
    str message;

    if (!canSave)
    {
        return;
    }

    if (!editedSource)
    {
        // Refuse to persist an empty source (it would blank the layout).
        info("@AAXWarehouseTools:SaveEmptySource");
        return;
    }

    // saveSourceToLayout returns [boolean success, str messageKey] (X++ has no scalar by-ref).
    result  = AAXWHSLabelPreviewController::saveSourceToLayout(layoutTableId, layoutRecId, editedSource);
    saved   = conPeek(result, 1);
    message = conPeek(result, 2);

    if (message)
    {
        info(message);
    }

    // On success, re-preview the SAVED state from the now-persisted layout (re-reads source),
    // so the image, translated ZPL and source panel all reflect what was written.
    if (saved)
    {
        element.refreshPreview();
    }
}

/// <summary>
/// The field whose value identifies a seed record to the user — the natural key shown in the
/// selector instead of RecId (e.g. WHSContainerTable -> ContainerId). Uses the table's
/// TitleField1; falls back to RecId only when the table exposes no title field.
/// </summary>
/// <returns>The identifier FieldId, or RecId (65534) when none is available.</returns>
private FieldId seedIdentifierFieldId()
{
    SysDictTable    dictTable;
    FieldId         titleFieldId;

    if (!seedTableId)
    {
        return fieldNum(Common, RecId);
    }

    dictTable    = SysDictTable::newTableId(seedTableId);
    titleFieldId = dictTable ? dictTable.titleField1() : 0;

    return titleFieldId ? titleFieldId : fieldNum(Common, RecId);
}

/// <summary>
/// Resolves the identifier text from the seed selector back to a RecId by matching the table's
/// identifier field (most-recent first if non-unique). RecId-fallback tables parse the text
/// directly. Empty / no match -> 0 (auto-resolve most-recent on the next Refresh).
/// </summary>
/// <param name = "_identifierText">The selector control text (an identifier, or empty).</param>
/// <returns>The matching record's RecId, or 0.</returns>
private RecId resolveSeedRecIdFromIdentifier(str _identifierText)
{
    FieldId                 idFieldId;
    Query                   query;
    QueryBuildDataSource    qbds;
    QueryRun                queryRun;

    if (!_identifierText || !seedTableId)
    {
        return 0;
    }

    idFieldId = element.seedIdentifierFieldId();

    // No natural identifier: the control text is the RecId itself (legacy behavior).
    if (idFieldId == fieldNum(Common, RecId))
    {
        return str2int64(_identifierText);
    }

    query = new Query();
    qbds  = query.addDataSource(seedTableId);
    qbds.addRange(idFieldId).value(queryValue(_identifierText));
    qbds.addSortField(fieldNum(Common, RecId), SortOrder::Descending);

    queryRun = new QueryRun(query);
    if (queryRun.next())
    {
        return queryRun.getNo(1).RecId;
    }

    return 0;
}

/// <summary>
/// The identifier text to DISPLAY in the seed selector for a given RecId (the table's
/// identifier-field value, e.g. ContainerId). Empty when there is no record / no selection.
/// </summary>
/// <param name = "_seedRecId">The selected seed record's RecId (0 = none).</param>
/// <returns>The display identifier, or an empty string.</returns>
private str seedRecordIdentifierText(RecId _seedRecId)
{
    FieldId idFieldId;
    Common  seedBuffer;

    if (!_seedRecId || !seedTableId)
    {
        return '';
    }

    idFieldId = element.seedIdentifierFieldId();

    if (idFieldId == fieldNum(Common, RecId))
    {
        return int642str(_seedRecId);
    }

    seedBuffer = new DictTable(seedTableId).makeRecord();
    select firstonly seedBuffer
        where seedBuffer.RecId == _seedRecId;

    return seedBuffer.RecId ? any2Str(seedBuffer.(idFieldId)) : '';
}

/// <summary>
/// Stores the seed record chosen in the data-source selector. The selector text is the
/// record's natural identifier (e.g. ContainerId), resolved back to a RecId here.
/// Empty / no match means "auto-resolve most-recent" on the next Refresh (selectedSeedRecId 0).
/// </summary>
/// <param name = "_identifierText">The selector control text (an identifier, or empty).</param>
public void setSelectedSeedRecId(str _identifierText)
{
    selectedSeedRecId = element.resolveSeedRecIdFromIdentifier(_identifierText);
}

/// <summary>
/// Enables/disables the Width/Height/DPI inputs to match the "Override label size" checkbox.
/// The checkbox itself stays enabled; only the three numeric inputs follow its state.
/// </summary>
/// <param name = "_enabled">True when the override is on (inputs editable).</param>
public void applySizeControlsEnabled(boolean _enabled)
{
    SizeWidthIn.enabled(_enabled);
    SizeHeightIn.enabled(_enabled);
    SizeDpi.enabled(_enabled);
}

/// <summary>
/// Computes the render size-override arguments from the "Label size" box, as a packed
/// container [real widthMm, real heightMm, int dpmm] for the controller render calls.
/// </summary>
/// <returns>
/// [widthMm, heightMm, dpmm]. All ZERO when the override checkbox is off or width/height are not
/// both &gt; 0 — which tells the renderer to use the label own ^PW/^LL (or the 4x6 fallback).
/// </returns>
/// <remarks>
/// Unit conversions (verified): inches -&gt; mm is *25.4; DPI -&gt; dpmm (int) is
/// real2int(round(dpi / 25.4, 1.0)) — nearest integer dpmm (203-&gt;8, 300-&gt;12, 600-&gt;24). dpmm
/// 0 lets the controller/wrapper apply the configured density default (8 dpmm). X++ has no
/// scalar by-ref, so the three values are returned in a container and unpacked by the caller.
/// </remarks>
private container sizeOverrideArgs()
{
    real widthMm  = 0;
    real heightMm = 0;
    int  dpmm     = 0;

    // Only honor the override when the box is checked AND both dimensions are positive; an
    // incomplete size would otherwise force a degenerate render (the user clicks Refresh).
    if (OverrideSizeCheck.value() && SizeWidthIn.realValue() > 0 && SizeHeightIn.realValue() > 0)
    {
        widthMm  = SizeWidthIn.realValue()  * 25.4;   // inches -> mm
        heightMm = SizeHeightIn.realValue() * 25.4;   // inches -> mm

        // DPI -> dpmm (int): nearest integer dots/mm. 0 (or non-positive DPI) defers to the
        // configured density default in AAXZplRenderService.renderToPngList.
        if (SizeDpi.value() > 0)
        {
            dpmm = real2int(round(SizeDpi.value() / 25.4, 1.0));
        }
    }

    return [widthMm, heightMm, dpmm];
}

/// <summary>
/// Runs a generic record lookup over the runtime seed table for the data-source selector.
/// The lookup RETURNS the table's natural identifier (e.g. ContainerId) as the
/// displayed/captured value — NOT the RecId — and shows TitleField2 as an extra column.
/// </summary>
/// <param name = "_control">The selector control the lookup is attached to.</param>
/// <remarks>
/// SysTableLookup over the runtime tableId, ordered most-recent first. The returned identifier
/// is resolved back to a RecId in setSelectedSeedRecId via the same identifier field.
/// </remarks>
public void lookupSeedRecord(FormStringControl _control)
{
    const FieldId RecIdFieldId = 65534; // Platform RecId FieldId.

    if (!seedTableId)
    {
        return;
    }

    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(seedTableId, _control);
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(seedTableId);
    SysDictTable            dictTable = SysDictTable::newTableId(seedTableId);
    FieldId                 idFieldId = element.seedIdentifierFieldId();
    FieldId                 titleField2Id = dictTable ? dictTable.titleField2() : 0;

    // Most-recent first, matching the auto-resolve default.
    qbds.addSortField(RecIdFieldId, SortOrder::Descending);

    // The natural identifier (e.g. ContainerId) is the RETURNED/displayed value, not RecId.
    sysTableLookup.addLookupfield(idFieldId);

    // Extra context column (e.g. ShipmentId for containers), when distinct from the identifier.
    if (titleField2Id && titleField2Id != idFieldId)
    {
        sysTableLookup.addLookupField(titleField2Id);
    }

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

/// <summary>Navigates to the previous label page.</summary>
public void clicked()
{
    super();
    element.showPage(currentIndex - 1);
}

/// <summary>Navigates to the next label page.</summary>
public void clicked()
{
    super();
    element.showPage(currentIndex + 1);
}

/// <summary>Downloads the currently displayed PNG.</summary>
public void clicked()
{
    super();
    element.downloadCurrentPage();
}

/// <summary>Rotates the current page 90 degrees clockwise (Feature 1, unlimited clicks).</summary>
public void clicked()
{
    super();
    element.rotateCurrentPage();
}

/// <summary>Re-renders the preview from the edited SOURCE text without saving (Feature 3).</summary>
public void clicked()
{
    super();
    element.previewEdits();
}

/// <summary>Saves the edited raw SOURCE ZPL back to the layout (Feature 3).</summary>
public void clicked()
{
    super();
    element.saveSource();
}

/// <summary>Generic RecId lookup over the runtime seed table.</summary>
public void lookup()
{
    // Do NOT call super(): SysTableLookup::performFormLookup drives the lookup form itself.
    element.lookupSeedRecord(this);
}

/// <summary>Captures the chosen record's RecId from the control text.</summary>
public boolean modified()
{
    boolean ret = super();

    // The lookup returns the RecId as the control value; an empty/cleared field means
    // "auto-resolve most-recent" (selectedSeedRecId == 0). Refresh applies it.
    element.setSelectedSeedRecId(this.text());

    return ret;
}

/// <summary>Re-renders the preview using the selected seed record.</summary>
public void clicked()
{
    super();
    element.refreshPreview();
}

/// <summary>
/// Enables/disables the Width/Height/DPI inputs to follow the override toggle. Does NOT
/// auto-render — the user clicks Refresh/Preview to re-render at the new size (kept simple).
/// </summary>
public void clicked()
{
    super();
    element.applySizeControlsEnabled(this.value());
}
